var viewContentGR = new GlideRecord('sn_map_core_view_content');
viewContentGR.addActiveQuery();
viewContentGR.addNullQuery('floor');
viewContentGR.addNullQuery('place');
viewContentGR.addNullQuery('place_type');
viewContentGR.addNullQuery('layer');
viewContentGR.addNullQuery('layer_type');
viewContentGR.addNullQuery('connector');
viewContentGR.addNullQuery('connector_type');
viewContentGR.query();
viewContentGR.setValue('building_or_campus', true);
viewContentGR.setWorkflow(false);
viewContentGR.updateMultiple();
